package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.widget.*;import android.view.*;import android.text.InputType;import org.json.*;
public final class BodyEditor {
 private static int dp(Activity a,int n){return Math.round(n*a.getResources().getDisplayMetrics().density);}
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival.runtimeprobe.EmbeddedGateway").getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static String message(Exception ex){Throwable cause=ex.getCause();return String.valueOf(cause==null?ex.getMessage():cause.getMessage());}
 private static void error(Activity a,Exception ex){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Could not save measurements").setMessage(message(ex)).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout panel,JSONObject player){Button button=new Button(a);button.setText("Height & Weight");button.setAllCaps(false);button.setMinHeight(dp(a,48));button.setOnClickListener(v->{button.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui7_body_get",player));a.runOnUiThread(()->{button.setEnabled(true);if(!a.isFinishing())form(a,player,data);});}catch(Exception ex){a.runOnUiThread(()->{button.setEnabled(true);error(a,ex);});}},"PlayerMeasurementsLoad").start();});panel.addView(button,new LinearLayout.LayoutParams(-1,-2));}
 private static EditText field(Activity a,LinearLayout col,String label,int value){TextView t=new TextView(a);t.setText(label);t.setTextColor(0xffdcecf7);col.addView(t);EditText e=new EditText(a);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setSingleLine(true);e.setText(String.valueOf(value));e.setTextColor(0xfff5fbff);e.setMinHeight(dp(a,48));col.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
 private static void form(Activity a,JSONObject player,JSONObject data){
  ScrollView scroll=new ScrollView(a);LinearLayout col=new LinearLayout(a);col.setOrientation(1);col.setPadding(dp(a,20),dp(a,16),dp(a,20),dp(a,16));col.setBackgroundColor(0xff101f38);scroll.addView(col);
  EditText height=field(a,col,"Height · 140–220 cm",data.optInt("height",180)),weight=field(a,col,"Weight · 40–130 kg",data.optInt("weight",75));TextView note=new TextView(a);note.setText("Save before entering the game. Applies to this card's body measurements.");note.setTextColor(0xffa8bed2);note.setPadding(0,dp(a,12),0,0);col.addView(note);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Height & Weight").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.show();ResponsiveUi.fit(a,dialog);
  dialog.getButton(-1).setOnClickListener(v->{try{int h=Integer.parseInt(height.getText().toString().trim()),w=Integer.parseInt(weight.getText().toString().trim());if(h<140||h>220){height.setError("140–220 cm");return;}if(w<40||w>130){weight.setError("40–130 kg");return;}JSONObject req=new JSONObject(player.toString());req.put("height",h);req.put("weight",w);dialog.getButton(-1).setEnabled(false);new Thread(()->{try{manage(a,"ui7_body_apply",req);a.runOnUiThread(()->{dialog.dismiss();Toast.makeText(a,"Measurements saved",Toast.LENGTH_SHORT).show();});}catch(Exception ex){a.runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);error(a,ex);});}},"PlayerMeasurementsSave").start();}catch(Exception ex){error(a,ex);}});
 }
}
